using System.Text.Json;
using System.Text.Json.Serialization;

namespace DotaAiCoach.MlInference.Tests;

/// <summary>
/// Deserialization shape for tools/DotaAiCoach.Training/tests/fixtures/onnx_parity/*.json,
/// generated by scripts/export_parity_fixtures.py -- see docs/adr/0024.
/// Each fixture records a full named input feature dict plus the
/// pre-export model's raw output, its isotonic-calibrated output (where
/// applicable), and the ONNX model's own raw output, so C# tests can
/// reconstruct an equivalent call and assert true numeric parity, not
/// just structural correctness.
/// </summary>
public sealed class OnnxParityFixture
{
    [JsonPropertyName("metadata")]
    public required OnnxParityMetadata Metadata { get; init; }

    [JsonPropertyName("cases")]
    public required List<OnnxParityCase> Cases { get; init; }

    public static OnnxParityFixture Load(string path)
    {
        var json = File.ReadAllText(path);
        return JsonSerializer.Deserialize<OnnxParityFixture>(json)
            ?? throw new InvalidOperationException($"Could not parse ONNX parity fixture at {path}");
    }
}

public sealed class OnnxParityMetadata
{
    [JsonPropertyName("source_model_id")]
    public required string SourceModelId { get; init; }

    [JsonPropertyName("feature_order")]
    public required List<string> FeatureOrder { get; init; }

    [JsonPropertyName("n_cases")]
    public required int NCases { get; init; }

    [JsonPropertyName("max_abs_diff_raw_vs_onnx_achieved")]
    public required double MaxAbsDiffRawVsOnnxAchieved { get; init; }
}

public sealed class OnnxParityCase
{
    [JsonPropertyName("case_name")]
    public required string CaseName { get; init; }

    [JsonPropertyName("description")]
    public required string Description { get; init; }

    [JsonPropertyName("input")]
    public required Dictionary<string, double> Input { get; init; }

    [JsonPropertyName("expected_raw_output")]
    public required double ExpectedRawOutput { get; init; }

    [JsonPropertyName("expected_calibrated_output")]
    public double? ExpectedCalibratedOutput { get; init; }

    [JsonPropertyName("expected_onnx_output")]
    public required double ExpectedOnnxOutput { get; init; }
}
